INSERT INTO public.lesson_parts VALUES (1, 'قواعد التكامل', 'التكامل أول حاجة خالص هو عملية عكسية للاشتقاق، فساعات بنسميه المشتقة العكسية. التكامل ليه قواعد وليه طرق.
أول قاعدة: الثابت اضربه في س. لو عايز تكامل س أس رقم، زود على الأس واحد واقسم على الأس الجديد أو اضرب في مقلوبه، بس القاعدة دي بتطبق بشرط إن الأس ميبقاش بسالب واحد. تكامل هـ أس س بيدي هـ أس س، وتكامل هـ أس سالب س بيدي سالب هـ أس سالب س. ١ على س تكاملها لوغاريتم (لن) مقياس س. أ على س تدي أ لوغاريتم مقياس س. أ على ب س تدي أ على ب لوغاريتم مقياس س، وهكذا. الدوال المثلثية: بكامل ست دوال مثلثية بس، وخلي بالك مين هما الستة اللي بعرف أكاملهم وكمان زاويتهم من الدرجة الأولى: جا، جتا، قا تربيع، قتا تربيع، قا ظا، قتا ظتا. اتنين عاديين، اتنين متربعين، اتنين مضروبين. الجا تكاملها سالب جتا، الجتا تكاملها جا، القا تربيع تكاملها ظا، القتا تربيع تكاملها سالب ظتا. قا ظا تكاملها قا، وقتا ظتا تكاملها سالب قتا. وبنكامل أي واحدة فيهم إزاي لو الزاوية من الدرجة الأولى؟ بنروح قاسمين على معامل س بتاع الزاوية في تكامل الدالة، يعني مثلاً جا(أ س + ب) تكاملها سالب جتا، فتبقى سالب ١ على أ جتا الزاوية. قاعدة الكسر: عشان أكامله لازم يبقى البسط اشتقاق المقام، لو حصل بيبقى التكامل بيدي لوغاريتم مقياس المقام. قاعدة الدالة الأسية: عشان أكاملها لازم تبقى مشتقة الأس مضروبة فيها، لو حصل ده بيديني الدالة الأسية نفسها. وفيه قاعدة تانية محفوظة للدالة الأسية: لو الأس بتاعها من الدرجة الأولى فبكاملها على طول بإني أقول ١ على معامل س بتاع الأس في الدالة الأسية. قاعدة القوس: عشان أكامله لازم يبقى مضروب في مشتقة اللي جوه القوس، لو حصل يبقى ساعتها بزود على أس القوس واحد واقسم على الأس الجديد. تكامل الأسية الغير طبيعية: دي اكتبها عشان بتتنسي، مثلاً ٣ أس أ س، اعتبر الثلاثة في دماغك كأنها هـ وكامل، فدي أسية والأس من الدرجة الأولى هنقول ١ على معامل س في هـ أس أ س، ولما تخلص تشيل الـ هـ وتحط ٣ وتقسم تحت على لوغاريتم ٣ الأساس.', '', '', 1);
INSERT INTO public.lesson_parts VALUES (2, 'حاجات تاخد بالك منها فالقواعد', 'لما يجيلي تكامل حاجة في مشتقتها زي جا س × جتا س، دي تعتبر دالة في مشتقتها فاللي قدامي ده قوس، بتميزها إنك تلاقي حاجة في مشتقتها فبتعتبر ده قوس أس واحد وتكامل ده بإنك تزود على الأس واحد وتضرب في مقلوبه. زي دي: ١ على س في لوغاريتم س للأساس هـ، دالة في مشتقتها يبقى هيديني قوس أزود على الأس واحد واضرب في المقلوب. من أشهر التكاملات إنه يجيبلك لوغاريتم س للأساس هـ على س، فتاخد الـ س ترميها فوق في البسط أس سالب واحد، كده بقى البسط اشتقاق المقام، هيديني لوغاريتم مقياس المقام زائد الثابت. ملاحظة وإنت بتحل: لو فيه تبسيط يتعمل وإنت بتحل تعمله وش، لو لمحت حاجة تمرجحها (قاعدة دوال مثلثية، أسس، لوغاريتمات) لازم تعملها لأنك لو معملتش كده مش هتحل. التبسيط في التكامل مش رفاهية، ده أمر عكس الاشتقاق، أنا ببسط وأنا بكامل عشان أحل.', '', '', 2);
INSERT INTO public.lesson_parts VALUES (3, 'طرق التكامل', 'لو جالك سؤال مش على قاعدة ومش على صورة من الصور اللي عندنا والتبسيط منفعش، هتروح للطرق: يا تعويض يا تجزيء. التعويض: مناسب مع الأقواس أكتر والكسور اللي مش عارف أكاملها ككسور. طريقة التعويض مع الأقواس إنك بتعوض عن اللي جوه القوس بأي حاجة (ص مثلاً)، وبعدين تجيب القديم بدلالة الجديد (س بدلالة ص) وتجيب التفاضلي، وبعدين تعوض في التكامل وتحل. ناس تانية بتساوي القوس كله بـ ص، ده شغال وده شغال. خلي بالك إن القوس اللي جواه من الدرجة الأولى مش هتعرف تكامله إلا لو بره فيه رقم، واللي جواه من الدرجة التانية مش هتعرف تكامله إلا لو بره فيه دالة من الدرجة الأولى. وتاخد بالك وإنت شغال تعويض إن لو قابلك جذور ماتاخدش جذر وإنت بتعوض عشان هترجع تعمل قوس تاني. التجزيء: آخر حاجة بروح لها، وخلي بالك لو فيه تكامل يتحل بالقواعد ماينفعش يتحل بالتجزيء. بستخدمه لو أنا مش عارف أحل بالقاعدة وفي نفس الوقت التجزيء مناسب مع دالتين مضروبين في بعض فيهم واحدة أسية وواحدة مثلثية مثلاً. طريقة التجزيء بعمل عمود تفاضل وتكامل، بنزل الدالة اللي هفاضلها والدالة اللي هكاملها. بيبقى نفسنا دايماً نفاضل كثيرات الحدود (س أس رقم) ونكامل أي دالة تانية بشرط نكون بنعرف نكامل الدالة التانية. بنكامل لحد ما نشق البطيخة أو نكمل زجزاج (بنكمل لو الدالة اشتقاقها هيوصل للصفر والتانية بنعرف نكاملها تاني، ساعتها الإشارات بتبقى موجب سالب موجب سالب). لو فيه لوغاريتم وإنت هتجزأ، وش اللوغاريتم هيتفاضل وماتتكاملش، ونكامل اللي جنبه. الأساس في القاعدة دي إن اللي هنفاضله بنسميه ص واللي هنكامله بنسميه د ع، والتكامل بيساوي ص ع - تكامل ع د ص.', '', '', 3);
INSERT INTO public.lesson_parts VALUES (4, 'ملاحظات على طرق التكامل', 'زي ما قلتلك لو فيه لوغاريتم في التجزيء هتفاضله وش. تاني ملحوظة إنك لو جزأت الأقواس هينفع وهيطلع ناتج مختلف شكلاً عن التعويض بس الاتنين صح. والحاجات اللي بتتحل بالقواعد لا تجزأ.', '', '', 4);
INSERT INTO public.lesson_parts VALUES (5, 'خواص التكامل', 'التكامل بيتوزع في الجمع والطرح، ما بيتوزعش في الضرب والقسمة. الثابت يترمي بره عادي. لو اشتقيت التكامل يديك الدالة من غير ثابت. لو كاملت مشتقة الدالة تديك الدالة بس زائد ثابت لأن التكامل عكس الاشتقاق. المشتقة العكسية للدالة يعني كامل الدالة. تفاضلي أي حاجة بيساوي مشتقة الحاجة في د س. يعني لو جابلك كامل س تربيع بالنسبة لـ س تكعيب دي تتفك بالقاعدة ويبقى تكامل ٣ س أس ٤ د س. ومثلاً تكامل قا أس ٤ س د(ظا س)، د(ظا س) تتفك لمشتقة الظا في د س (قا تربيع س د س) فتبقى دالة في مشتقتها. الثابت شفاط، يعني الثابت لو اتجمع مع أي رقم بينزل في الآخر برضه كـ (ثابت).', '', '', 5);
INSERT INTO public.lesson_parts VALUES (6, 'ملاحظات', 'التكاملات اللي ليها أكتر من ناتج ده وضع طبيعي جداً. مثلاً تكامل جا س جتا س ممكن أتعامل معاه إنه جا أس واحد في مشتقتها جتا فتدينا نص جا تربيع س، وممكن أتعامل معاه إنه جتا في مشتقتها سالب جا فتدينا سالب نص جتا تربيع س، وممكن أتعامل معاه إنه نص جا ضعف الزاوية وأكمله، والتلاتة صح ومتكافئين لأن الثابت بيشفط الأرقام. نفس الكلام في تكامل قا تربيع ظا. طريقة التفكير في التكامل: بشوف المنظر قدامي قوس ولا كسر ولا أسية، لو قوس لازم مشتقة اللي جواه بره، مش موجودة بشوف تبسيط، مفيش بشتغل بالطرق. وفيه قاعدة لو قابلت هـ أس س مضروبة في (دالة + مشتقتها) التكامل ده بيدي هـ أس س في الدالة + ثابت.', '', '', 6);
INSERT INTO public.lesson_parts VALUES (7, 'خلي بالك', 'عايز ألفت انتباهك لكذا حاجة. بص على المنظر ده: تكامل (جا² س × جتا س). في المقابل، قبل ما نتكلم في استخدام الآلة، تكامل (جا² س) لوحدها. نفس الكلام هنا: تكامل (جتا² س × جا س)، وفي المقابل تكامل (جتا² س) لوحدها. ونفس الكلام: تكامل (ظا² س × قا² س)، وفي المقابل تكامل (ظا² س) لوحدها. بالنسبة لتكامل (جا² س × جتا س)، دي عبارة عن قوس في مشتقة اللي جوه القوس، يبقى ده على صورة القوس، تكاملها (1/3 جا³ س + ثابت). كملنا ده كقوس، بس لو كانت (جا² س) لوحدها هل مشتقة اللي جوه القوس (اللي هي جتا س) موجودة؟ لأ، يبقى ده مش على صورة القوس ومش هعرف أكاملها كده. هل الدالة (جا² س) ليها قاعدة تكامل عندي؟ لأ، اللي ليهم قاعدة وهم متربعين هما (قا² س) و (قتا² س). الـ (جا² س) دي أنا ممكن أفُكها لـ (1 - جتا² س)، طب ما أنت كده بتحل المشكلة بنفس المشكلة! فالأسهل هنا أفُك دي لقانون ضعف الزاوية: (1/2 - 1/2 جتا 2س). ولما اتفكت كده بقى سهل تكاملها، النص تكامله (1/2 س)، ودي هقسم على معامل س فهتبقى (1/4 جا 2س). نفس الكلام مع (جتا² س × جا س)، ده قوس في اشتقاق اللي جوه القوس، بس هضرب في سالب جوه وبره، فتكاملها (-1/3 جتا³ س). بينما لو (جتا² س) لوحدها، مشتقة اللي جوه القوس مش موجودة، فهنحولها لـ (1/2 + 1/2 جتا ضعف الزاوية)، ودي تكاملها هيديك (1/2 س) زائد (1/4 جا 2س). حاجة زي تكامل (ظا² س × قا² س)، ده قوس ومشتقة اللي جوه القوس موجودة، يبقى هزود على الأس واحد وأضرب في مقلوبه. إنما لو (ظا² س) لوحدها، مشتقة اللي جوه القوس مش موجودة، والـ (ظا² س) مش من الدوال الستة المثلثية اللي بعرف أكاملهم مباشرة، بس ممكن أحولها لدالة بعرف أكاملها، إن (ظا² س = قا² س - 1). تكامل (قا² س) بـ (ظا س) ده محفوظ، وتكامل السالب 1 بـ (-س). حاجة كمان تاخد بالك منها: لما يجيلي دالة مثلثية زاويتها من الدرجة الأولى، عشان أعرف أكاملها لازم يكون مضروب فيها رقم ثابت مثلاً، لأن سهل أقسّم عليه. بينما لو دالة مثلثية زاويتها من الدرجة الأولى ومضروبة في متغير (س)، ساعتها هتحلها بالتجزيء. خلي بالك من الحاجات دي. تعال بقى نتكلم إزاي لو اتزنقنا في تكامل غير محدد نحله على الآلة.', '', '', 7);
INSERT INTO public.lesson_parts VALUES (8, 'مثالين مهمين', 'لو جالي تكاملات زي دي، هنحلها الأول كخطوات وبعدين نشوف إزاي ممكن نحلها بتجربة الاختيارات أو بالآلة. لو هحل تكامل بالشكل ده بايدي، أنا لمحت إن المقدار ده مربع كامل فهحلله: جذر الأول وجذر الأخير والكل أس 2، فهيبقى (2س - 1)². وعندي القوس أصلاً مرفوع لأس 7، فهيبقى الكل أس 14. هنقسم على نفس الأساس ونطرح الأسس فتصفى في الآخر على (2س - 1)¹². ده تكامل قوس، محتاج مشتقة اللي جوه القوس اللي هي 2، فهضرب في 2 جوه وفي نص بره. يبقى التكامل على الصورة القياسية: نص في القوس بعد ما أزود أسه وأقسم على الأس الجديد، فهتبقى (1/26 (2س - 1)¹³). حبيت أحله بتجربة الاختيارات بالآلة: هاخد الدالة اللي جوه التكامل وأكتبها على الآلة وأعوض مكان الـ س برقم (وليكن 1، بشرط ما يبوظش الدالة)، هيطلع الناتج مثلاً 1. الناتج ده هسجله على جنب. بعد كده أروح أشتق الاختيارات وأعوض فيها بنفس الـ س (اللي هي 1). الاختيار اللي مشتقته هتديني نفس الناتج يبقى هو الإجابة الصح. طب لو دوال مثلثية؟ هكامل دي بايدي الأول: هاخد (جا² س) عامل مشترك، هيفضل (1 + ظا² س) اللي هي (قا² س). الـ (قا² س) بتنزل في المقام بـ (جتا² س). هتبقى (جا² س / جتا² س) اللي هي بتدينا (ظا² س). ظا² مابنعرفش نكاملها فهنحولها لـ (قا² س - 1)، وتكامل (قا² س) بـ (ظا س) وتكامل السالب واحد بـ (-س). لو عايز تعملها على الآلة (تكامل دوال مثلثية): لازم تظبط الآلة الأول على نظام الريديان (Radian). بعدين تعوض في الدالة الأصلية بأي زاوية بالقياس الدائري (مثلاً π/6). هيطلعلك رقم تسجله. وبعدين تروح تشتق الاختيارات الموجودة وتعوض فيها بنفس الزاوية. الاختيار اللي هيديك نفس الناتج هو الإجابة الصح. طبعاً دي طريقة بتاخد وقت، بس معاك لو عطلت.', '', '', 8);
INSERT INTO public.lesson_parts VALUES (9, 'التكامل المحدد', 'التكامل المحدد، أول حاجة حسابه وشروطه. التكامل من (أ) لـ (ب) للدالة د(س) بالنسبة لـ س: اللي محتاج تفهمه إن الحدود دي تمثل الفترة المغلقة من أ لـ ب، مش حدود وخلاص. ولما بتكامل بالنسبة لـ س، فحدودك سينات، ولو كاملت بالنسبة لـ ص فحدودك صادات. ومن أساسيات التكامل إن لما أكامل بالنسبة لـ س لازم الدالة تبقى دالة في س. بنحسب التكامل إزاي؟ كأننا مش شايفين الحدود، بنكامل الدالة عادي جداً تطلع لنا دالة جديدة، بس مابنحطش ثابت التكامل. بعدين نعوض بالحدود: التعويض عن س باللي فوق ناقص التعويض عن س باللي تحت. الناتج من التكامل المحدد بيبقى رقم، الرقم ده ممكن يبقى موجب أو سالب أو صفر، لأنه مش دايماً بيعبر عن مساحة. شرط حسابه إن الدالة تكون متصلة على الفترة دي، لو مش متصلة لا يمكن إجراء التكامل. بالنسبة للملاحظات عليه مع التجزيء ومع التعويض: في التجزيء، لو بكامل دالتين (زي تكامل من 1 لـ هـ لـ لوغاريتم س)، بتفاضل اللوغاريتم وتكامل الدالة التانية. ولما تخلص، الجزء اللي اتكامل وخلص تحط عليه حدود التكامل وتطرح منه تكامل الجزء التاني وتحطله حدوده برضه. مع التعويض بتزيد خطوة: لما تساوي اللي جوه القوس بمتغير جديد (زي ص) وتجيب التفاضلي، لازم تغير الحدود من سينات لصادات! تعوض بحدود الـ س عشان تجيب حدود الـ ص الجديدة، وتكمل المسألة.', '', '', 9);
INSERT INTO public.lesson_parts VALUES (10, 'خواص التكامل المحدد', 'التكامل المحدد زيه زي غير المحدد، بيتوزع في الجمع والطرح، ومابيتوزعش في الضرب والقسمة، والأرقام تترمي بره عادي. لكن له خواص إضافية:
1. شقلب واقلب: لو شقلبت الحدود، تغير الإشارة.
2. لو هتشتق ناتج التكامل المحدد، هيديك صفر لأنه في النهاية رقم ثابت (إلا لو الحدود فيها متغيرات).
3. لو جمعت تكامل من أ لـ ب + تكامل من ب لـ أ لنفس الدالة، الناتج صفر. ولما تكامل وتلاقي الحدود زي بعض (من أ لـ أ) فالتكامل بصفر بدون ما تحل.
4. خاصية الدوال الزوجية والفردية: لو الدالة فردية وبنكامل من (-أ) لـ (أ)، التكامل بصفر. لو زوجية، بيساوي ضعف التكامل من صفر لـ (أ).
5. خاصية الشريحة: لو الدالة زوجية وتكاملها من أ لـ ب برقم، يبقى تكاملها من (-ب) لـ (-أ) بنفس الرقم. أما في الفردية هتلاقيه بالسالب.
6. خاصية الدمج: لو قابلت تكاملين مجموعين، الدالة هي الدالة، وفي حد مشترك (عامل قطر أو مقص)، وباقي الحدود مختلفة، تدمجهم بتكامل واحد بالحدود المختلفة دي. لو جابلك تكامل مجموع لدالتين مختلفتين بنفس الحدود، ده مش دمج، ده تكامل متوزع. التكامل المحدد بنحسبه على الآلة لو الحدود والدالة مفيهاش أي مجهول (وما تنساش نظام الريديان للدوال المثلثية). أما لو الحدود أو الدالة فيهم مجهول، لازم تكامل بايدك. ولو الدالة أنت أصلاً متعرفش قاعدتها الرياضية إيه ومجهولة، ساعتها مش هتعرف تكامل بايدك ولا بالآلة، ولازم تستخدم خواص التكامل أو تترجمها لمساحات.', '', '', 10);
INSERT INTO public.lesson_parts VALUES (11, 'المساحات وحالات المساحات بين منحنى ومحور س', 'المساحات في المستوى (المساحة بين منحنى ومحور س). لو المنحنى مرسوم فوق، فالمساحة هي التكامل. لو المنحنى مرسوم تحت محور س، المساحة هي سالب التكامل. ولو المنحنى جزء منه فوق وجزء منه تحت، المساحة هتساوي التكامل اللي فوق ناقص التكامل اللي تحت. عشان كده بنقول إن التكامل مش هو المساحة، وإنما التكامل تم تطويعه عشان يجيب المساحة.', '', '', 11);
INSERT INTO public.lesson_parts VALUES (12, 'التكامل الدائري', 'لازم تحفظ الشكل ده: ص = √(رقم - س²). دي معادلة نص دايرة مركزها نقطة الأصل، وطول نص قطرها هو جذر الرقم ده. فلما يقابلني تكامل من (-أ) لـ (أ) للمعادلة دي، ده بيدي مباشرة مساحة نص الدايرة (1/2 π أ²). ولو التكامل من (صفر) لـ (أ) أو من (-أ) لـ (صفر)، بيدي مساحة ربع الدايرة.', '', '', 12);
INSERT INTO public.lesson_parts VALUES (13, 'خطوات حساب المساحة وملاحظات عليها', 'خطوات حساب المساحة: ترسم المنحنيات والخطوط اللي عندك، وتظلل المنطقة المطلوب حساب مساحتها بدقة شديدة وتشوفها محصورة بين مين ومين. لو غير كلمة في السؤال (مثلاً بدل محور س قال محور ص)، المنطقة بتتغير والحالة بتتغير. أحياناً بنلجأ للتقسيم في حالتين:
1. لو المنطقة مش محصورة بين منحنى واحد ومحور س، ولكنها محصورة بين كذا منحنى أو خط في فترات مختلفة، بنقسمها لمساحتين ونجيب مجموعهم.
2. لو المنطقة محصورة بين منحنيين، بنجيب المساحة اللي تحت المنحنى الأعلى، ناقص المساحة اللي تحت المنحنى الأسفل.', '', '', 13);
INSERT INTO public.lesson_parts VALUES (14, 'الحجوم الدورانية', 'الحجوم: لو دارت منطقة مستوية دورة كاملة حول محور السينات، بينشأ مجسم دوراني. حجمه بيتجاب بالقانون: الحجم = π × تكامل مربع الدالة (ص²) بالنسبة لـ س. يعني كأنك بتجيب مساحة بس تضرب في π وتربع الدالة. ملاحظات نظرية: لو مستطيل دار دورة كاملة حول أحد أضلاعه، بينشأ أسطوانة دائرية قائمة. لو مثلث قائم دار حول أحد ضلعي القائمة، بينشأ مخروط دائري قائم. ولو نص دايرة دارت حول قطرها، بتنشأ كورة.', '', '', 14);
INSERT INTO public.lesson_parts VALUES (15, 'العلاقات', 'اللخبطة كلها في علاقة المساحة بالتكامل والعكس. المساحة هي مجموع المساحات مهما حصل، والتكامل هو مجموع التكاملات مهما حصل، الاتنين دول مفيش فيهم حالات. لكن علاقة المساحة بالتكامل هي اللي بتترجم لحالات: لو هترجم المساحة لتكامل وكان المنحنى فوق يبقى المساحة = التكامل، لو تحت يبقى المساحة = سالب التكامل. ولو هترجم التكامل لمساحة: لو الدالة فوق فالتكامل هو المساحة، لو تحت التكامل هو سالب المساحة. إمتى نرمي على الآلة؟ لو الحدود معروفة والدالة معروفة ومفيش أي مجهول. إمتى نكامل بإيدنا؟ لو الحدود أو الدالة فيها مجاهيل، أو لو جوه التكامل دالة بنعرف نكاملها. إمتى نستخدم الخواص ونترجم لمساحات؟ لو الدالة مش عارفين قاعدتها (زي د(س)) وما ينفعش نكاملها بالطرق العادية، ساعتها يا نستخدم الخواص أو نترجمها للمساحة المحصورة طبقا للحالات الثلاثة.', '', '', 15);
INSERT INTO public.lesson_parts VALUES (16, 'حبشتكنات مهمة أوي أوي أوي', 'المساحات والحجوم والمنحنيات البارامترية آخر حاجة يا باشا في حبشتكنات هذا الفرع، أول نقطة نبدأ بيها: أي مسألة مساحات وحجوم فيها منحنى بارامتري لازم تحولها لعلاقة مباشرة. يعني لما يجي يقولي المساحة المحصورة بين منحنى الدالة (ص = ن تربيع) و (س = 2 ن)، إوعى في المساحات والحجوم تشتغل بارامتري. ده منحنى واحد، أنا عايز المساحة المحصورة ما بينه هو ومحور س، لازم تحولها لعلاقة مباشرة بإنك تخلص من الوسيط، فهتقول (ن = س/2)، وتعوض في الدالة وتربع، يبقى (ص = ربع س تربيع). كده إنت عايز المساحة ما بين المنحنى ده ومحور س. الخلاصة: لو جاتلي مسألة مساحات وحجوم فيها بارامتري لازم تحولها لعلاقة مباشرة، دي أول نقطة.', '', '', 16);
INSERT INTO public.lesson_parts VALUES (17, 'حبشتكنات مهمة أوي أوي أوي 2', 'مسائل سلوك الدالة أي مسألة سلوك دالة (تزايد، تناقص، تحدب، قيم محلية، قيم مطلقة) لازم تخلي العلاقة صريحة. تلاقيه جه في الامتحان قالك: (هـ أس دالة س = 3 س تربيع - 1)، هات النقط الحرجة للدالة أو هات تزايد وتناقص الدالة. مش هينفع أشتغل عليها كده، لازم أخلي (دالة س) في طرف والـ (س) في طرف، فهُدخل على الطرفين لوغاريتم؛ هتنزل الأس وتبقى (دالة س) مضروبة في (لوغاريتم هـ للأساس هـ) بتساوي (لوغاريتم 3 س تربيع - 1 للأساس هـ)، وبما إن لوغاريتم هـ للأساس هـ بواحد، يبقى هي دي الدالة اللي أنا هشتغل عليها. أو مثلاً يجي في الامتحان يقولي: (س ص = هـ أس س) هات القيم المحلية. ده سؤال سلوك دالة، مش هينفع أشتغل كده، لازم أقسم وأخلي (ص) في طرف، والدالة اللي فيها (س) في الناحية التانية وأبدأ أشتغل.', '', '', 16);
INSERT INTO public.lesson_parts VALUES (18, 'حبشتكنات مهمة أوي أوي أوي 3', 'تفاضل وتكامل دالة المقياس والدوال المجزأة المقياس عرفنا بنشتقه إزاي؛ المقياس لما نشتقه ممكن نعمله بالقاعدة اللي قولناها لكم، أو إننا نعيد تعريفه ونحوله لدالة مجزأة ونشتقها. أما لما نكامل المقياس؛ لازم تعيد تعريفه لأن مفيش قاعدة. والدالة المجزأة لما تكاملها لازم تتكامل تكامل محدد، مينفعش غير محدد لأنها معرفة في فترات. وبالتالي لما يجيلي تكامل مقياس أو تكامل دالة مجزأة لازم أشتغلها تكامل محدد وأشوف أنا شغال في أنهي فترة وأحط أنهي دالة. يعني على سبيل المثال، لما يقولي (دالة س = س - 2 لما س أكبر من أو تساوي 1)، و (دالة س = 3 س - 4 لما س أصغر من 1)، ويقولي هات تكامل الدالة من (-2) لـ (5). دي دالة مجزأة أكاملها إزاي؟ أولاً بتحط الرقم اللي اختلف حواليه تعريف الدالة وتحط حدود التكامل. لما تبقى (س) أقل من 1 الدالة هتكون (3 س - 4)، ولما تبقى (س) أكبر من 1 الدالة هتكون (س - 2). فالتكامل ده هيبقى تكاملين: من (-2) لـ (1) بكامل الدالة الأولى، ومن (1) لـ (5) بكامل الدالة التانية. ده التعامل مع الدوال المجزأة في التكامل، ودالة المقياس نفس التعامل بالظبط بس هيزيد عليها خطوة إنك هتعيد تعريف المقياس وتكتبه بالشكل المجزأ ده.', '', '', 16);
INSERT INTO public.lesson_parts VALUES (19, 'حبشتكنات مهمة أوي أوي أوي 4', 'ميل المماس وفصل المتغيرات آخر حاجة يا صديقي وهي "ميل المماس لمنحنى عند أي نقطة عليه"، اللفظ ده معناه إن أنا بديك المشتقة الأولى اللي هي (د ص / د س) أو (د شرطة س). لما أديك المشتقة الأولى وأطلب الدالة، هتكامل المشتقة الأولى عشان تجيب الدالة. رمز (د شرطة س) مابيستخدمش إلا لو المشتقة دالة في (س) فقط، وساعتها بجيب الدالة بإن أنا أكامل المشتقة تكامل مباشر على طول. أما إذا كانت المشتقة مش دالة في (س) فقط، فلا يجوز استخدام الرمز ده، ولازم أسمي المشتقة (د ص / د س)، وساعتها مش هقدر أكامل تكامل مباشر عشان أجيب الدالة؛ لازم أفصل المتغيرات، أخلي جنب (د س) الدالة اللي في (س)، وجنب (د ص) الدالة اللي في (ص)، ثم نكامل الطرفين. ولما تكامل الطرفين الثابت بيتحط في طرف واحد فيهم وتشتغل عادي.', '', '', 16);
INSERT INTO public.lesson_parts VALUES (20, 'حبشتكنات مهمة أوي أوي أوي 5', 'العلاقة المباشرة بين التفاضل والتكامل حاجة أخيرة تاخد بالك منها، لما آجي أقولك إن (تكامل س تكعيب - 3) بيساوي (دالة س + ثابت)، وأقولك هات (د شرطة 1). فإنت هتروح تكامل عشان تجيب الدالة وبعدين تشتقها؟ تبقى غبي! لأن لو ده تكامله بيدي اللي في الطرف التاني، يبقى أنا عارف إن اشتقاق الطرف التاني هو اللي جوه التكامل؛ يعني اللي جوه التكامل ده هو نفسه (د شرطة س). فلو طلب (د شرطة 1) تتجاب على طول بالتعويض المباشر في الدالة اللي جوه التكامل، يعني هتبقى (1 تكعيب - 3 = -2).', '', '', 16);


