INSERT INTO public.student_history VALUES (15, 1, 1, 'student', 'لا مفهمتش', NULL, '2026-08-21 20:55:15.314946');
INSERT INTO public.student_history VALUES (16, 1, 1, 'ai', 'إيه يا عم ده! ولا يهمك يا "بلف" هههههه، تعال نروّق الكلام مع بعض كده وبدون أي كلكعة.. أخوك أبو عصام هيسطهالك على الآخر، ركز معايا حبة.

التكامل ده يا سيدي هو "العكس" بتاع التفاضل (بنرجع الخطوة لوراء).
تعال نلخص أهم القواعد في نقط بسيطة:

1- **الرقم الثابت:**
لو بتكامل رقم لوحده، ارمي جنبه س.
مثال: تكامل 5 دس = 5س + ث.

2- **س المرفوعة لأس (س^ن):**
زود على الأس واحد، واقسم على الأس الجديد.
مثال: تكامل (س^2) دس = (1 على 3) س^3 + ث.
*(بشرط الأس ميكونش سالب 1)*.

3- **الكسر الغشاش (1 على س):**
أول ما تشوف س تحت في المقام والأس بتاعها 1، تكاملها بيكون لوغاريتم مقياس المقام للأساس هـ.
قاعدة مهمة: لو لقيت (البسط هو مشتقة المقام)، الناتج علطول = لوغاريتم |المقام| للأساس هـ.

4- **الدالة الأسية (هـ^س):**
بتنزل زي ما هي! ولو الأس مضروب في رقم زي (أ س)، نقسم على معامل س بره.
مثال: تكامل هـ^(3س) دس = (1 على 3) هـ^(3س) + ث.

5- **الدوال المثلثية (الستة اللي بنعرف نكاملهم):**
- تكامل جا س = سالب جتا س.
- تكامل جتا س = جا س.
- تكامل قا^2 س = ظا س.
- تكامل قتا^2 س = سالب ظتا س.
- تكامل (قا س ظا س) = قا س.
- تكامل (قتا س ظتا س) = سالب قتا س.
*(ولو الزاوية فيها رقم قبل س مثل "أ س"، بنضرب بره في "1 على أ")*.

---

ها يا بطل؟ حاسس إن الصورة وضحت دلوقتي ولا لسه فيه نقطة معصلقة معاك؟ قولي فهمت ولا إيه علشان أطمن عليك!', NULL, '2026-08-21 20:55:15.314946');
INSERT INTO public.student_history VALUES (17, 1, 1, 'student', 'عايز حل السؤال ده', 'data:image/jpeg;base64,', '2026-08-21 21:00:44.701367');
INSERT INTO public.student_history VALUES (18, 1, 1, 'ai', 'يا هلا بيك يا بطل! سؤال ممتاز وفكرته حلوة بتعتمد على "اللعب بالمقام والبسط".. تعالى نحله مع بعض خطوة بخطوة وبأبسط طريقة.

المطلوب: تكامل (س على (س^2 - 6س + 9)) دس

**الخطوة الأولى (نظرة معلم):**
بص كده على المقام (س^2 - 6س + 9).. ده مقدار ثلاثي مربع كامل! 
يعني نقدر نكتبه على شكل قوس تربيع: (س - 3)^2

فيصبح التكامل:
تكامل (س على (س - 3)^2) دس

---

**الخطوة الثانية (فكرة صايعة في البسط):**
البسط فيه (س).. إيه رأيك ننقص 3 ونزود 3 عشان نخلي البسط فيه (س - 3) شبه القوس اللي تحت؟
يبقى المقدار هينكتب كده:
تكامل ((س - 3 + 3) على (س - 3)^2) دس

---

**الخطوة الثالثة (توزيع البسط على المقام):**
هنقسم المقدار لكسرين:
تكامل [ (س - 3) على (س - 3)^2 + 3 على (س - 3)^2 ] دس

نختصر الكسر الأول: (س - 3) تطير مع واحدة من اللي في المقام.
والكسر الثاني: نطلع القوس من المقام للبسط بأس سالب.

فيتبقى عندنا:
تكامل [ 1 على (س - 3) + 3 (س - 3)^-2 ] دس

---

**الخطوة الرابعة (التكامل المباشر):**
نكامل كل جزء لوحده عادي جداً:

1. تكامل (1 على (س - 3)) = لوغاريتم |س - 3| للأساس هـ (لأن البسط مشتقة المقام).
2. تكامل (3 (س - 3)^-2) = بنزود على الأس 1 ونقسم على الأس الجديد، فيبقى: 3 (س - 3)^-1 على -1 = - (3 على (س - 3)).

---

**الناتج النهائي:**
لوغاريتم |س - 3| للأساس هـ - (3 على (س - 3)) + ث

---

طمني يا بطل، طالعة معاك مضبوطة ولا في خطوة مش واضحة؟ أنت من الناس المطروشة المشطشطة في الرياضة وأثق فيك!

#لو_عايز_ال60_خليك_مع_احمد_عصام_الدين', NULL, '2026-08-21 21:00:44.701367');
INSERT INTO public.student_history VALUES (19, 1, 1, 'student', 'كنت عايز شرح السؤال ده', 'data:image/jpeg;base64,', '2026-08-21 21:10:07.252433');
INSERT INTO public.student_history VALUES (20, 1, 1, 'ai', 'أهلاً بيك يا بطل! معاك أستاذك أبو عصام.

السؤال ده ممتاذ جداً وبيعتمد على فكرة ذكية في التبسيط قبل ما تبدأ تكامل، تعال نفصص المسألة خطوة بخطوة بطريقة سهلة:

المسألة هي: **تكامل (س على (س^2 - 6س + 9)) دس**

---

### **الخطوة الأولى: تبسيط المقام**
لو ركزت في المقام (س^2 - 6س + 9)، هتلاحظ إنه "مربع كامل"، يعني نقدر نخليه قوس أس 2 كده:
**(س - 3)^2**

يبقى شكل المسألة بعد التبسيط:
**تكامل (س على (س - 3)^2) دس**

---

### **الخطوة الثانية: الحركة الذكية في البسط**
عايزين نخلي البسط شبه القوس اللي تحت عشان نعرف نختصر. هنعمل إيه؟ هنطرح 3 ونزود 3 في البسط! (كأننا مضفناش حاجة):
البسط يبقى: **(س - 3 + 3)**

فتبقى المسألة:
**تكامل [ (س - 3 + 3) على (س - 3)^2 ] دس**

---

### **الخطوة الثالثة: تجزئة الكسر**
هنوزع البسط على المقام، فيطلع عندنا كسرين:
1) (س - 3) على (س - 3)^2  ==>  نختصر تبقى: **(1 على (س - 3))**
2) **(3 على (س - 3)^2)** ==> نطلع القوس فوق بعكس إشارة الأس تبقى: **3 (س - 3)^-2**

يبقى التكامل الجديد:
**تكامل [ (1 على (س - 3)) + 3 (س - 3)^-2 ] دس**

---

### **الخطوة الرابعة: نكامل كل جزء لوحده**
1) **تكامل (1 على (س - 3)):**
بما إن البسط مشتقة المقام، يبقى الناتج هو: **لوغاريتم |س - 3| للأساس هـ**

2) **تكامل 3 (س - 3)^-2:**
دي قاعدة القوس، بنزود على الأس واحد ونقسم على الأس الجديد:
زود على الأس 1 تبقى (-1)، واقسم على (-1)، فيطلع الناتج: **-3 (س - 3)^-1**
واللي هي نفسها: **- (3 على (س - 3))**

---

### **الناتج النهائي:**
**لوغاريتم |س - 3| للأساس هـ - (3 على (س - 3)) + ث**

---

طمني يا وحش، الفكرة وصلت ودخلت دماغك تمام؟ لو فهمتها صح تبقى مطروش مشطشط! 

وقولي عشان نقول مع بعض الشعار بتاعنا:
**#لو_عايز_ال60_خليك_مع_احمد_عصام_الدين**', NULL, '2026-08-21 21:10:07.252433');
INSERT INTO public.student_history VALUES (21, 1, 1, 'student', 'لا مفهمتش', NULL, '2026-08-21 21:11:59.864666');
INSERT INTO public.student_history VALUES (22, 1, 1, 'ai', 'ولا يهمك يا بلف! عادي جداً، ما هو أخوك أبو عصام مش هيسيبك غير وانت هاضم الدرس ده ومقفل فيه. تعال ندردش فيها بالبلدي وبأبسط طريقة:

التكامل ده يا سيدي عكس الاشتقاق (التفاضل)، يعني بنرجع الدالة لأصلها. عندنا شوية قواعد بنمشي عليها زي الأكل والشرب:

1. **العدد الثابت:** أي رقم لوحده، حط جنبه س. يعني تكامل 5 بالنسبة لـ س = 5 س + ث.
2. **س مرفوعة لأس:** زود على الأس واحد واقسم على الأس الجديد. 
   - مثال: تكامل س^2 = (1 على 3) س^3 + ث. (بس بشرط الأس ميكونش سالب 1).
3. **قاعدة الكسر:** لو لقيت البسط هو اشتقاق المقام، يبقى الناتج على طول = لوغاريتم مقياس المقام للأساس هـ.
   - ومنها: تكامل (1 على س) = لوغاريتم مقياس س للأساس هـ.
4. **الدالة الأسية (هـ^س):** غلبانة وطيبة، تكامل هـ^س بيفضل زي ما هو هـ^س! 
   - ولو الأس مضروب في رقم (زي هـ^أ س)، بنقسم على الرقم ده: (1 على أ) هـ^(أ س).
5. **الدوال المثلثية (الستة المشهورين):** بنكامل 6 دوال بس زاويتهم من الدرجة الأولى، وما تنساش تقسم على معامل س اللي جوه الزاوية:
   - جا(أ س) تكاملها = سالب (1 على أ) جتا(أ س)
   - جتا(أ س) تكاملها = (1 على أ) جا(أ س)
   - قا^2(أ س) تكاملها = (1 على أ) ظا(أ س)
   - قتا^2(أ س) تكاملها = سالب (1 على أ) ظتا(أ س)
   - قا(أ س) ظا(أ س) تكاملها = (1 على أ) قا(أ س)
   - قتا(أ س) ظتا(أ س) تكاملها = سالب (1 على أ) قتا(أ س)

ها يا وحش، كده المعنى جاب معاك ورست على بر، ولا لسه فيه حاجة معصلقة عشان نقول الشعار بتاعنا؟ طمني!', NULL, '2026-08-21 21:11:59.864666');
