INSERT INTO public.student_history VALUES (24, 1, 1, 'ai', 'أهلاً بيك يا بطل، معاك أستاذك أبو عصام، وركز معايا كويس جداً لأن السؤال ده فكرته جميلة وسهلة جداً لو لمحناها صح!

المسألة بتقول:
تكامل (س على (س^2 - 6س + 9)) دس.

تعال نمشي خطوة بخطوة عشان نفهم اللعبة:

1) **الخطوة الأولى (نظرة على المقام):**
المقام عندك (س^2 - 6س + 9)، لو ركزت فيه هتلاقيه مربع كامل، يعني نقدر نخليه قوس تربيع كده: (س - 3)^2.
فالمسألة بقى شكلها:
تكامل [س على (س - 3)^2] دس.

2) **الخطوة الثانية (حركة زكاوة في البسط):**
عايزين نخلي البسط شبه اللي جوه القوس اللي في المقام (س - 3)، هنعمل إيه؟ هنطرح 3 ونزود 3 في البسط!
يبقى البسط هيتحول لـ: (س - 3 + 3).

3) **الخطوة الثالثة (نقسم الكسر):**
نفصل البسط على المقام، فتبقى:
تكامل [ (س - 3) على (س - 3)^2 + 3 على (س - 3)^2 ] دس.

نختصر الكسر الأول، ونرفع القوس في الكسر الثاني فوق بأس سالب:
تكامل [ 1 على (س - 3) + 3 (س - 3)^-2 ] دس.

4) **الخطوة الأخيرة (نكامل كل جزء):**
- الجزء الأول: (1 على (س - 3))، هتلاحظ إن البسط مشتقة المقام! يبقى تكاملها بيساوي: لوغاريتم |س - 3| للأساس هـ.
- الجزء الثاني: (3 (س - 3)^-2)، دي قاعدة القوس، نزود على الأس 1 ونقسم على الأس الجديد (اللي هو -1):
فتبقى: - (3 على (س - 3)).

---

**الناتج النهائي للتكامل:**
لوغاريتم |س - 3| للأساس هـ - (3 على (س - 3)) + ث.

---

ها يا بطل؟ طمني طريقتها دخلت دماغك ولا فيه حاجة واقفة معاك؟
لو لقطتها وسلكت معاك تبقى "مطروش ومشطشط"!

