INSERT INTO public.student_history VALUES (26, 1, 1, 'ai', 'يا بلف! 😃 ولا يهمك يا بطل، العيب مش عليك، التكامل ده محتاج يتاخد على هادي وبمزاج.. تعالي نفصص الكلام ده واحدة واحدة وبأبسط طريقة في الدنيا.

بص يا سيدي، التكامل هو "العملية العكسية للاشتقاق" (يعني بنرجع المسألة لأصلها). اعتبرها لعبة وليها قواعد أساسية:

1) **تكامل أي رقم ثابت:** بنلزق فيه س على طول.
مثال: تكامل 5 دس = 5س + ث.

2) **تكامل س مرفوعة لـ أُس:** زود على الأس 1 واقسم على الأس الجديد (يعني اضرب في 1 على الأس الجديد).
مثال: تكامل (س^2) دس = (1 على 3) س^3 + ث.
*(بشرط الأس ميكونش سالب 1)*.

3) **حالة خاصة (1 على س):** تكاملها بيدينا لوغاريتم مقياس س للأساس هـ.

4) **الدوال المثلثية (لو الزاوية أ س):**
- تكامل جا(أ س) = (سالب 1 على أ) جتا(أ س) + ث.
- تكامل جتا(أ س) = (1 على أ) جا(أ س) + ث.

ها يا بطل؟ قل لي بصراحة، القواعد البسيطة دي دخلت دماغك ورست ولا لسة؟ رد عليا عشان نطمن ونكمل باقي الأفكار!', NULL, '2026-08-21 21:19:19.403945');
INSERT INTO public.student_history VALUES (27, 1, 1, 'student', 'قواعد التكامل', NULL, '2026-08-22 15:26:47.255528');
INSERT INTO public.student_history VALUES (28, 1, 1, 'ai', 'أهلاً بيك يا بطل، معاك أبو عصام.. ركز معايا كويس عشان التكامل ده لعبتنا، والتكامل ببساطة هو العملية العكسية للاشتقاق، وبنسميه المشتقة العكسية.

عشان تفرم التكامل، جمعتلك القواعد الأساسية في كبسولات سهلة:

1. تكامل الثابت:
أي رقم ثابت بتضربه في س.
مثال: تكامل 5 دس = 5 س + ث.

2. تكامل س مرفوعة لأس:
بنزود على الأس واحد ونقسم على الأس الجديد (بشرط الأس ميكونش سالب 1).
مثال: تكامل س^3 دس = (1 على 4) س^4 + ث.

3. تكامل الكسر (لو البسط مشتقة المقام):
- تكامل (1 على س) دس = لوغاريتم مقياس س للأساس هـ + ث.
- القاعدة العامة: لو البسط هو اشتقاق المقام، يبقى الناتج = لوغاريتم مقياس المقام للأساس هـ + ث.

4. تكامل الدالة الأسية الطبيعية:
- تكامل هـ^س دس = هـ^س + ث.
- لو الأس من الدرجة الأولى زي هـ^(أ س + ب)، تكاملها = (1 على أ) هـ^(أ س + ب) + ث.
- لو الدالة الأسية مضروبة في مشتقة الأس بتاعها، التكامل بيدينا الدالة الأسية نفسها.

5. تكامل الدوال المثلثية (عندنا 6 دوال بس بنعرف نكاملهم ولازم الزاوية تكون درجة أولى):
بنقسم برة على معامل س في الزاوية:
- تكامل جا(أ س) دس = سالب (1 على أ) جتا(أ س) + ث
- تكامل جتا(أ س) دس = (1 على أ) جا(أ س) + ث
- تكامل قا^2(أ س) دس = (1 على أ) ظا(أ س) + ث
- تكامل قتا^2(أ س) دس = سالب (1 على أ) ظتا(أ س) + ث
- تكامل [قا(أ س) ظا(أ س)] دس = (1 على أ) قا(أ س) + ث
- تكامل [قتا(أ س) ظتا(أ س)] دس = سالب (1 على أ) قتا(أ س) + ث

6. قاعدة القوس:
لو عندك قوس مرفوع لأس، ومضروب برة في مشتقة اللي جوه القوس، بتزود على أس القوس واحد وتقسم على الأس الجديد.

طمني يا وحش، تمام كده ولا في حتة عايز نعيدها تاني؟', NULL, '2026-08-22 15:26:47.255528');


